R=[
("कम सोडियम वाले अचार",
 "ये कम सोडियम वाले अचार ढके रहने तक फ़्रिज में दो महीने तक चल सकते हैं। इन्हें बनाना आसान है और ये आपकी खान-पान योजना को पटरी पर रखते हुए भोजन में कुरकुरा और स्वादिष्ट साइड जोड़ने का बढ़िया तरीका हैं।",
 "10","6 अचार",
 ["1 1/2 कप सफ़ेद सिरका","1 छोटा चम्मच साबुत काली मिर्च","1 छोटा चम्मच साबुत धनिया","1 बड़ा चम्मच सूखा सोआ (या 2 बड़े चम्मच ताज़ा)","2 बड़े चम्मच स्टीविया","1/2 छोटा चम्मच नमक","1/4 छोटा चम्मच कुटी हुई लाल मिर्च के फ्लेक्स (वैकल्पिक)","2 मध्यम खीरे (1/4 इंच के गोल टुकड़ों में कटे हुए (लगभग 60 टुकड़े))","1/2 छोटा प्याज़ (पतला कटा हुआ)","2 लहसुन की कलियाँ (पतली कटी हुई)"],
 ["एक मध्यम सॉसपैन में तेज़ आँच पर सिरका, साबुत काली मिर्च, साबुत धनिया, सोआ, स्टीविया, नमक और लाल मिर्च के फ्लेक्स (वैकल्पिक) मिलाएँ। उबाल आने दें, फिर आँच बंद कर दें और ठंडा होने के लिए एक तरफ़ रख दें।","खीरे, प्याज़ और लहसुन को ढक्कन वाले एक क्वार्ट आकार के काँच के जार, या किसी और गरमी सहने वाले बर्तन में कसकर भरें। तरल को खीरे और प्याज़ पर डालें और सुनिश्चित करें कि सारी सब्ज़ियाँ पूरी तरह डूबी हों।","ढक्कन को कसकर बंद करें और परोसने से पहले कम से कम 1 दिन फ़्रिज में रखें।"]),
("कुरकुरी बेक्ड ब्रोकली",
 "यह एक स्वादिष्ट और आसान सब्ज़ी का व्यंजन है जिसे आप बजट के अनुकूल जमी हुई ब्रोकली के पैकेट से बना सकते हैं। अपनी आधी थाली को ब्रोकली, गाजर, हरी पत्तेदार सब्ज़ियों जैसी बिना स्टार्च वाली सब्ज़ियों से भरने का लक्ष्य रखें!",
 "4","रेसिपी का 1/4 हिस्सा (लगभग 122 ग्राम)",
 ["1 स्प्रे, 0.25 ग्राम नॉनस्टिक कुकिंग स्प्रे","1 पैकेट जमी हुई ब्रोकली के फूल (16 औंस)","1 छोटा चम्मच लहसुन पाउडर","1/2 छोटा चम्मच प्याज़ पाउडर","1 बड़ा चम्मच सोया सॉस (कम सोडियम वाला)","1 बड़ा चम्मच ज़ैतून का तेल"],
 ["ओवन को 375 डिग्री F पर पहले से गरम करें।","कुकी शीट पर नॉनस्टिक कुकिंग स्प्रे लगाकर तैयार करें।","ब्रोकली को पिघलाकर पानी निथार लें।","बाकी सामग्री को एक गैलन आकार के ज़िपलॉक बैग में मिलाएँ। ब्रोकली के फूल प्लास्टिक बैग में डालें और लिपटने तक हिलाएँ।","फूलों को तैयार बेकिंग शीट पर उनके बीच जगह छोड़कर रखें। बचा हुआ मैरिनेड फेंक दें।","45 मिनट से एक घंटे तक बेक करें। ब्रोकली अंदर से नरम लेकिन किनारों पर कुरकुरी होगी।"]),
("शाकाहारी शेफ़र्ड्स पाई",
 "इस आरामदायक क्लासिक का आनंद इस भरोसे के साथ लें कि इसे मधुमेह के अनुकूल बनाया गया है। बीफ़ कीमे की जगह दालों और सब्ज़ियों का मिश्रण इस्तेमाल करने से कैलोरी और वसा कम हो जाती है लेकिन स्वाद और निखर जाता है।",
 "8","1 कप",
 ["1 स्प्रे, 0.25 ग्राम नॉनस्टिक कुकिंग स्प्रे","1 पाउंड भूरी मसूर (सूखी)","32 औंस वेजिटेबल स्टॉक (कम सोडियम वाला)","1 बड़ा चम्मच ज़ैतून का तेल","16 औंस सफ़ेद (बटन) मशरूम (कटे हुए)","1 बड़ा पीला प्याज़ (छोटे टुकड़ों में कटा हुआ)","2 बड़ी गाजरें (छिली और छोटे टुकड़ों में कटी हुई)","2 डंठल अजवाइन (छोटे टुकड़ों में कटे हुए)","1 पाउंड ताज़ी हरी बीन्स (सिरे काटकर छोटे टुकड़ों में कटी हुई)","2 लहसुन की कलियाँ (बारीक कटी हुई)","1 1/2 कप बिना मीठा बादाम का दूध (बाँटकर)","1 छोटा चम्मच नमक (बाँटकर)","1/2 छोटा चम्मच काली मिर्च","1/4 कप ताज़ा अजमोद (कटा हुआ)"],
 ["ओवन को 375 डिग्री F पर पहले से गरम करें। 9x13 इंच की बेकिंग डिश पर कुकिंग स्प्रे लगाएँ।","जब मसूर पक रही हो, तब एक बड़े सॉते पैन में मध्यम-तेज़ आँच पर ज़ैतून का तेल डालें। मशरूम डालें और अंदर तक पकने और सारा पानी सूखने तक भूनें।","प्याज़, गाजर, अजवाइन, हरी बीन्स और लहसुन डालें और प्याज़ पारदर्शी होने और गाजर के नरम होना शुरू होने तक भूनें।","एक कप पकी हुई मसूर और उसका कोई भी तरल सब्ज़ियों में डालें और मिलाने के लिए चलाएँ। बाकी मसूर अलग रख लें। 1 कप बादाम का दूध सब्ज़ियों में डालें। मिलाने के लिए चलाएँ। 1/2 छोटा चम्मच नमक (वैकल्पिक) और काली मिर्च डालें।","सब्ज़ियों के मिश्रण को 9x13 इंच की बेकिंग पैन में डालें। एक तरफ़ रख दें।","एक बड़े कटोरे में बची हुई मसूर को बाकी बादाम के दूध, बचे हुए 1/2 छोटा चम्मच नमक (वैकल्पिक) और अजमोद के साथ मिलाएँ। मिश्रण को इलेक्ट्रिक मिक्सर से फूलने तक फेंटें।","मसूर को मसूर/सब्ज़ी के मिश्रण के ऊपर चम्मच से डालें और पूरे ऊपरी हिस्से को ढकने के लिए धीरे से फैला दें।","फ़ॉइल से ढक दें और 45 मिनट बेक करें। ढक्कन हटाकर 30 मिनट और बेक करें, या जब तक ऊपरी हिस्सा सुनहरा भूरा होने न लगे और भरावन में बुलबुले न उठने लगें।","परोसने से पहले शेफ़र्ड्स पाई को ओवन से बाहर 10 मिनट आराम करने दें।"]),
("सूरजमुखी-ब्रोकली लेयर सलाद",
 "आप इस स्वादिष्ट, पोषक तत्वों से भरपूर सलाद को ज़रूर आज़माना चाहेंगे, जो गर्मियों की पिकनिक के लिए एकदम सही है। हर सर्विंग विटामिन सी से भरपूर है।",
 "6","1 1/2 कप",
 ["8 कप ब्रोकली (8 कप, निवाले के आकार के टुकड़ों में कटी हुई)","1/2 मध्यम लाल प्याज़ (पतला कटा हुआ)","1/3 कप किशमिश (या सूखी खट्टी चेरी)","1/3 कप चेडर चीज़ (ताज़ा कसा हुआ, एक्स्ट्रा शार्प)","1/2 कप सादा दही (फैट-फ़्री)","2 बड़े चम्मच एप्पल साइडर सिरका","1 1/2 बड़े चम्मच शहद","1 बड़ा चम्मच लाइट मेयोनेज़","2 बड़े चम्मच सूरजमुखी के बीज (नमकीन, भुने हुए)"],
 ["एक बड़े काँच के ट्राइफ़ल या सर्विंग बाउल में ब्रोकली, प्याज़, किशमिश (या सूखी खट्टी चेरी) और चीज़ की परतें लगाएँ।","एक छोटे कटोरे में दही, सिरका, शहद और मेयोनेज़ फेंटकर मिला लें। ड्रेसिंग को सलाद पर बराबर डालें।","ढककर परोसने के लिए तैयार होने तक फ़्रिज में रखें। परोसने से ठीक पहले सूरजमुखी के बीज छिड़कें।"]),
("साबुत गेहूँ की हैंड पाई",
 "इन पाई के बेक हो जाने के बाद, इन्हें बाद की किसी तारीख़ पर आसान डिनर के लिए हवाबंद फ़्रीज़र बैग में जमाकर रखा जा सकता है।",
 "8","1 हैंड पाई",
 ["1 कप गुनगुना पानी (लगभग 100 डिग्री F)","1 बड़ा चम्मच कम कैलोरी वाला ब्राउन शुगर का विकल्प","1 पैकेट एक्टिव ड्राई यीस्ट","2 कप साबुत गेहूँ का आटा","1 स्प्रे, 0.25 ग्राम नॉनस्टिक कुकिंग स्प्रे","1 छोटा चम्मच ज़ैतून का तेल","8 औंस सफ़ेद (बटन) मशरूम (छोटे टुकड़ों में कटे हुए)","1 कप पका हुआ पालक","1 लहसुन की कली (बारीक कटी हुई)","1 1/2 छोटे चम्मच कोशर नमक (बाँटकर इस्तेमाल करें)","1/2 छोटा चम्मच काली मिर्च","3/4 कप मोज़रेला चीज़ (कम वसा वाली)","1 बड़ा अंडा (1 बड़े चम्मच पानी के साथ फेंटा हुआ)"],
 ["डफ़ हुक अटैचमेंट लगा मिक्सर तैयार करें। अगर आपके पास मिक्सर नहीं है, तो फ़ूड प्रोसेसर तैयार करें।","गुनगुना पानी, ब्राउन शुगर का विकल्प और यीस्ट मिक्सिंग बाउल या फ़ूड प्रोसेसर के बाउल में डालें और यीस्ट को 5 मिनट तक सक्रिय होने दें। यीस्ट में झाग बनना शुरू हो जाना चाहिए।","आटा और 1 छोटा चम्मच कोशर नमक डालें और आटा मिलने तक धीमी गति पर मिलाएँ। अगर डफ़ हुक अटैचमेंट वाले मिक्सर का इस्तेमाल कर रहे हैं, तो गति मध्यम कर दें और आटे को 5 मिनट गूँधें। अगर फ़ूड प्रोसेसर का इस्तेमाल कर रहे हैं, तो आटे को साफ़, आटा छिड़के बोर्ड या काउंटरटॉप पर निकालें और हाथ से 5-7 मिनट गूँधें। अगर आटा बहुत चिपचिपा हो, तो एक-एक बड़ा चम्मच आटा तब तक डालें जब तक वह चिकना आटा न बन जाए।","गूँधे हुए आटे को कुकिंग स्प्रे लगे एक बड़े कटोरे में डालें, ढक दें और फूलने के लिए एक घंटे तक गरम जगह पर रखें।","जब आटा फूल रहा हो, तब ओवन को 400 डिग्री F पर पहले से गरम करें। बेकिंग शीट पर कुकिंग स्प्रे लगाएँ। एक तरफ़ रख दें।","एक मध्यम सॉते पैन में मध्यम-तेज़ आँच पर ज़ैतून का तेल गरम करें। मशरूम डालें और नरम होने और उनका सारा पानी सूखने तक भूनें।","एक मध्यम कटोरे में मशरूम, पालक, लहसुन, 1/2 छोटा चम्मच कोशर नमक, काली मिर्च और मोज़रेला चीज़ मिलाएँ। एक तरफ़ रख दें।","आटे को आठ गोलों में बाँटें और प्लास्टिक रैप से ढककर लगभग 15 मिनट आराम करने दें।","हर आटे के गोले को 1/4 इंच की मोटाई तक बेलें। हर गोले में भरावन का 1/8 हिस्सा (लगभग 1/2 कप) डालें। हैंड पाई बनाने के लिए मोड़ें और किनारों को दबाकर बंद करें। बाकी 8 आटे के गोलों के लिए यही प्रक्रिया दोहराएँ और बेकिंग शीट पर रखें।","हर पाई पर अंडे का घोल लगाएँ और 25 मिनट या सुनहरा भूरा होने तक बेक करें।"]),
("साउदर्न ब्रोकली सलाद",
 "यह ताज़गी भरा ब्रोकली सलाद किसी भी बारबेक्यू चिकन, ग्रिल्ड मछली या पोर्क चॉप के साथ अच्छा लगता है।",
 "6","2/3 कप",
 ["1/8 छोटा चम्मच काली मिर्च","1/2 छोटा चम्मच नमक","1 1/2 बड़े चम्मच शहद","1/4 कप सादा बिना वसा वाला ग्रीक योगर्ट","1/4 कप लाइट मेयोनेज़","1/3 कप चेडर चीज़ (कम वसा वाली, कसी हुई, 1 1/2 औंस)","3/4 कप अजवाइन (कटी हुई)","1/4 कप प्याज़ (बारीक कटा हुआ)","3 कप ब्रोकली के फूल"],
 ["एक मध्यम कटोरे में ब्रोकली, प्याज़, अजवाइन और चीज़ मिलाएँ; एक तरफ़ रख दें।","एक छोटे कटोरे में बाकी सामग्री मिलाएँ। मेयोनेज़ का मिश्रण सब्ज़ियों के मिश्रण में डालें और मिलाएँ।","ढककर कम से कम 2 घंटे फ़्रिज में रखें ताकि स्वाद आपस में घुल-मिल जाएँ।"]),
("काली बीन्स और मक्के का सलाद",
 "ताज़ा और स्वादिष्ट, यह लज़ीज़ काली बीन्स और मक्के का सलाद टेक्स-मेक्स खाने की इच्छा होने पर एक बढ़िया विकल्प है।",
 "8","3/4 कप",
 ["2 (15 औंस) डिब्बे काली बीन्स (कम सोडियम, छानकर और धोकर)","1 1/2 कप जमा हुआ मक्का (पिघलाया हुआ)","1 मध्यम लाल शिमला मिर्च (छोटे टुकड़ों में कटी हुई)","3/4 कप चेरी टमाटर (आधे कटे हुए)","1/4 मध्यम लाल प्याज़ (बारीक कटा हुआ)","1/4 कप ताज़ा हरा धनिया (कटा हुआ)","2 पूरे लाइम (रस निकाला हुआ)","3 बड़े चम्मच ज़ैतून का तेल","1 छोटा चम्मच पिसा जीरा","1/4 छोटा चम्मच कोशर नमक","1/2 छोटा चम्मच काली मिर्च","1 मध्यम एवोकाडो (कटा हुआ, परोसने के लिए)"],
 ["एक बड़े मिक्सिंग बाउल में काली बीन्स, पिघलाया हुआ मक्का, कटी हुई लाल शिमला मिर्च, चेरी टमाटर, कटा हुआ लाल प्याज़ और ताज़ा हरा धनिया मिलाएँ।","एक छोटे कटोरे में दोनों लाइम का रस निचोड़ें। ज़ैतून का तेल, पिसा जीरा, कोशर नमक और काली मिर्च डालें। मिलने तक फेंटें।","ड्रेसिंग को काली बीन्स और मक्के के मिश्रण पर डालें। सभी सामग्री को बराबर लपेटने के लिए अच्छी तरह मिलाएँ।","कटोरे को ढक दें और स्वाद आपस में घुलने के लिए कम से कम 30 मिनट फ़्रिज में रखें।","परोसने से पहले सलाद को धीरे से एक बार मिला लें। चाहें तो अतिरिक्त हरे धनिये और एवोकाडो के टुकड़ों से सजाएँ।"]),
("ह्यूमस और लाल शिमला मिर्च वाले अजवाइन के टुकड़े",
 "यह क्लासिक \"लकड़ी के लट्ठे पर चींटियाँ\" नाश्ते का एक नया रूप है। इस नमकीन संस्करण में मूँगफली के मक्खन की जगह ह्यूमस और किशमिश की जगह शिमला मिर्च के टुकड़े हैं। ह्यूमस के अलग-अलग स्वाद आज़माएँ - भुनी हुई लाल शिमला मिर्च वाला अच्छा रहेगा!",
 "4","3 टुकड़े",
 ["4 डंठल अजवाइन","4 बड़े चम्मच ह्यूमस","1/2 मध्यम लाल शिमला मिर्च (1/4 इंच के चौकोर टुकड़ों में कटी हुई)"],
 ["अजवाइन के हर डंठल में 1 बड़ा चम्मच ह्यूमस भरें, फिर हर डंठल को 3 बराबर टुकड़ों में काटें। अजवाइन के हर टुकड़े पर लाल शिमला मिर्च के 2 टुकड़े रखें।"]),
("घर का बना फलों से मीठा किया हुआ ग्रैनोला",
 "अपनी \"सेहत वाली छवि\" के बावजूद, बाज़ार से खरीदे ग्रैनोला में अक्सर वसा और अतिरिक्त चीनी भरी होती है। यह बेहद सरल रेसिपी अपनी मिठास सेब की प्यूरी से पाती है और इसमें कोई अतिरिक्त वसा नहीं है। दही के ऊपर डालने, बेक्ड चिकन पर परत चढ़ाने, या फलों वाली मिठाई पर कुरकुरी परत लगाने के लिए एकदम सही। भोजन की पहले से तैयारी के लिए बड़ी मात्रा बनाएँ और एक हफ़्ते तक सीलबंद जार में रखें।",
 "8","1/3 कप",
 ["1 1/2 कप पारंपरिक रोल्ड ओट्स","1/2 कप कटे हुए बादाम के पतले टुकड़े","1 छोटा चम्मच पिसी दालचीनी","1/2 कप बिना मीठी सेब की प्यूरी (एप्पलसॉस)","1/2 छोटा चम्मच वनीला एक्सट्रैक्ट"],
 ["ओवन को 300° F पर पहले से गरम करें। बेकिंग शीट पर बिना ब्लीच किया पार्चमेंट पेपर बिछाएँ।","एक मध्यम कटोरे में सारी सामग्री मिलाएँ। बेकिंग शीट पर एक समान परत में फैलाएँ।","ओवन में भुनने तक, लगभग 35 मिनट, बेक करें। चलाने की ज़रूरत नहीं है। ट्रे में ही कूलिंग रैक पर ठंडा करें। परोसें या एक हफ़्ते तक सीलबंद जार या डिब्बे में रखें।"]),
("तीखा मसूर स्ट्यू",
 "हमारा तीखा मसूर स्ट्यू आज़माएँ। सब्ज़ियों को भूनते समय एक छोटा चम्मच कुटी हुई लाल मिर्च के फ्लेक्स डालकर आप इस भरपेट स्ट्यू को और भी तीखा बना सकते हैं। या फिर सेब, इटैलियन या भूमध्यसागरीय स्वाद वाले चिकन सॉसेज का इस्तेमाल करके इसे कम तीखा रखें।",
 "9","1 कप",
 ["1 पूरा नॉनस्टिक कुकिंग स्प्रे","2 डंठल अजवाइन (मध्यम टुकड़ों में कटे हुए)","14 औंस तीखा चिकन सॉसेज (जलापेनो या एंडुइल)","1 मध्यम प्याज़ (छोटे टुकड़ों में कटा हुआ)","2 मध्यम गाजरें (छोटे टुकड़ों में कटी हुई)","1 मध्यम लाल शिमला मिर्च (छोटे टुकड़ों में कटी हुई)","3 कप पानी","14 1/2 औंस कम सोडियम वाला चिकन ब्रॉथ","1 कप सूखी मसूर","1 छोटा चम्मच काली मिर्च","1 तेज पत्ता","1/4 कप ताज़ा अजमोद (कटा हुआ)"],
 ["एक बड़े सूप के बर्तन पर कुकिंग स्प्रे लगाएँ। मध्यम-तेज़ आँच पर सॉसेज को हल्का भूरा होने तक भूनें।","अजवाइन, प्याज़, गाजर और लाल शिमला मिर्च बर्तन में डालें और मध्यम-तेज़ आँच पर लगभग 4 मिनट या प्याज़ के पारदर्शी होना शुरू होने तक भूनें।","पानी, ब्रॉथ, मसूर, नमक, काली मिर्च और तेज पत्ता डालें। उबाल आने दें और आँच कम करें। धीमी आँच पर 1 घंटे तक पकाएँ।","तेज पत्ता निकाल दें। अजमोद छिड़कें और परोसें।"]),
("भुनी लाल शिमला मिर्च वाली टमाटर की सॉस",
 "टमाटर में पोटेशियम अधिक होता है, यानी कम पोटेशियम वाले आहार पर किडनी रोग का प्रबंधन करने वाले व्यक्ति के लिए टमाटर की सॉस आमतौर पर वर्जित होती है। यह किडनी के अनुकूल सॉस आधे टमाटरों की जगह भुनी हुई लाल शिमला मिर्च का इस्तेमाल करती है, जिससे कम पोटेशियम वाली सॉस बनती है जिसे पास्ता, पिज़्ज़ा पर या रेसिपी में टमाटर की सॉस के विकल्प के रूप में इस्तेमाल किया जा सकता है। और इसका स्वाद भी बढ़िया है! आप बाज़ार से खरीदी भुनी हुई लाल शिमला मिर्च (सबसे कम सोडियम वाला विकल्प देखें) इस्तेमाल कर सकते हैं या घर पर लाल शिमला मिर्च भून सकते हैं। आप इस रेसिपी को आसानी से दोगुना या तीन गुना करके बड़ी मात्रा बना सकते हैं और कुछ बाद के लिए फ़्रीज़ कर सकते हैं।",
 "4","1/4 कप",
 ["1/4 छोटा चम्मच, या स्वादानुसार कुटी हुई लाल मिर्च के फ्लेक्स","1 छोटा चम्मच इटैलियन सीज़निंग","1/2 कप कम सोडियम वाली टमाटर की सॉस","1 लहसुन की कली","1/2 कप भुनी हुई लाल शिमला मिर्च (छानकर)"],
 ["शिमला मिर्च और लहसुन को फ़ूड प्रोसेसर या ब्लेंडर में डालें और चिकना होने तक प्रोसेस करें। टमाटर की सॉस, ज़ैतून का तेल और इटैलियन सीज़निंग डालें। अच्छी तरह मिलने तक प्रोसेस करें। पिज़्ज़ा, पास्ता पर या रेसिपी में टमाटर की सॉस के विकल्प के रूप में इस्तेमाल के लिए तैयार। इसे 3 दिन तक फ़्रिज में रखा जा सकता है या इस्तेमाल तक फ़्रीज़ किया जा सकता है।"]),
("ब्लूबेरी, 1/2 कप",
 "ब्लूबेरी की पोषण संबंधी जानकारी",
 "1","1/2 कप",
 ["1/2 कप ब्लूबेरी (धोई हुई)"],[]),
("आसान पालक रिकोटा एन्चिलादा",
 "इस आसान पालक रिकोटा एन्चिलादा रेसिपी के साथ चुपके से सब्ज़ियों की एक अतिरिक्त सर्विंग जोड़कर एन्चिलादा को सेहतमंद नया रूप दें। 30 मिनट में खाने के लिए तैयार, यह मधुमेह के अनुकूल व्यंजन निश्चित रूप से परिवार का नया पसंदीदा बन जाएगा!",
 "6","2 एन्चिलादा",
 ["1 छोटा चम्मच ज़ैतून का तेल","1 छोटा पीला प्याज़ (छोटे टुकड़ों में कटा हुआ)","1/4 छोटा चम्मच काली मिर्च","10 औंस जमा हुआ पालक (पिघलाया हुआ और अतिरिक्त पानी निचोड़ा हुआ)","4 औंस कम वसा वाला रिकोटा चीज़","7 औंस कॉटेज चीज़ (बिना वसा वाला)","12 मक्के की टॉर्टिला (5 इंच)","1 कप डिब्बाबंद लाल एन्चिलादा सॉस","1 1/2 औंस मॉन्टेरी जैक चीज़ (कसा हुआ)","1 गुच्छा हरा प्याज़ (स्कैलियन) (कटा हुआ)"],
 ["ओवन को 400 डिग्री F पर पहले से गरम करें।","एक बड़ी कड़ाही को मध्यम आँच पर गरम करें। तेल, प्याज़ और काली मिर्च डालें। बीच-बीच में चलाते हुए प्याज़ के नरम होने तक, 4-5 मिनट, पकाएँ।","पके हुए प्याज़ को एक बड़े कटोरे में डालें। पालक, रिकोटा और कॉटेज चीज़ डालें। मिलाने के लिए चलाएँ।","टॉर्टिला को गीले पेपर टॉवल में लपेटें और माइक्रोवेव में 30 सेकंड गरम करें।","बेकिंग डिश पर कुकिंग स्प्रे करें। पालक की भरावन को टॉर्टिला में बराबर बाँटें। लपेटें और जोड़ वाले हिस्से को नीचे रखकर बेकिंग डिश में रखें।","एन्चिलादा सॉस टॉर्टिला पर डालें। ऊपर कसा हुआ चीज़ डालें। चीज़ के पिघलकर बुलबुले आने तक, 10-15 मिनट, बेक करें।","एन्चिलादा को प्लेटों में बाँटें और ऊपर हरा प्याज़ डालें।"]),
("पकी हुई एडामेमे",
 "एडामेमे की पोषण संबंधी जानकारी",
 "1","1/2 कप पकी हुई",
 ["1/2 कप एडामेमे (पकी हुई)"],[]),
("चीज़ी फूलगोभी टॉट्स",
 "इन स्वादिष्ट छोटे टॉट्स को परिवार के लिए डिनर के साथ साइड के रूप में परोसें। ये क्लासिक टेटर टॉट्स का कहीं ज़्यादा सेहतमंद और मधुमेह के अनुकूल संस्करण तो हैं ही, साथ ही इनका स्वाद इतना मिलता-जुलता है कि हो सकता है उन्हें पता ही न चले कि वे फूलगोभी खा रहे हैं!",
 "7","5 टॉट्स",
 ["1 स्प्रे, 0.25 ग्राम नॉनस्टिक कुकिंग स्प्रे","1 फूलगोभी (छंटी हुई (लगभग 1 1/2 पाउंड))","1 बड़ा अंडा","1 बड़े अंडे की सफ़ेदी","1/2 कप चेडर चीज़ (कम वसा वाला, कसा हुआ)","1/3 कप ब्रेड क्रम्ब्स","2 डंठल हरा प्याज़ (स्कैलियन) (सफ़ेद और हरे हिस्से, बारीक कटे हुए)","1/2 छोटा चम्मच नमक (वैकल्पिक)","1/4 छोटा चम्मच काली मिर्च"],
 ["ओवन को 400 डिग्री F पर पहले से गरम करें। एक बड़ी या दो छोटी बेकिंग शीट पर कुकिंग स्प्रे लगाएँ। एक तरफ़ रख दें।","फूलगोभी को 10-12 मिनट या नरम होने तक भाप में पकाएँ। ठंडा होने के लिए एक तरफ़ रख दें। ठंडी होने पर फूलगोभी को बारीक काट लें।","बाकी सामग्री को कटी हुई फूलगोभी में मिलाएँ और मिश्रण को 10 मिनट आराम करने दें।","आराम के बाद मिश्रण को फिर से चलाएँ। 1 बड़े चम्मच के माप से फूलगोभी को स्प्रे की हुई बेकिंग शीट पर निकालें। गोले को टेटर-टॉट के आकार में ढालें। इसे दोहराकर 35 टॉट्स बनाएँ।","हर टॉट के ऊपर कुकिंग स्प्रे करें। 15 मिनट बेक करें। टॉट्स को पलटें और सुनहरा भूरा होने तक 10 मिनट और बेक करें।"]),
]
